<?php
require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';$user=Auth::requireRole('hospital');$hospital=current_hospital($user);$hid=(int)$hospital['id'];$type=$_GET['type']??'requests';header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="lifelink_hospital_'.$type.'_'.date('Ymd_His').'.csv"');$out=fopen('php://output','w');if($type==='transfers'){fputcsv($out,['ID','Supplying Hospital','Receiving Hospital','Blood Group','Units','Urgency','Status','Created','Completed']);$q=db()->prepare("SELECT t.*,hf.name from_name,ht.name to_name FROM blood_transfer_requests t JOIN hospitals hf ON hf.id=t.from_hospital_id JOIN hospitals ht ON ht.id=t.to_hospital_id WHERE t.from_hospital_id=? OR t.to_hospital_id=? ORDER BY t.created_at DESC");$q->execute([$hid,$hid]);foreach($q as $r)fputcsv($out,[$r['id'],$r['from_name'],$r['to_name'],$r['blood_group'],$r['units_requested'],$r['urgency'],$r['status'],$r['created_at'],$r['completed_at']]);audit('hospital_csv_export','hospital',$hid,['type'=>'transfers']);}else{fputcsv($out,['ID','Blood Group','Units Needed','Target Donors','Urgency','District','Status','Created','Expires']);$q=db()->prepare('SELECT * FROM emergency_requests WHERE hospital_id=? ORDER BY created_at DESC');$q->execute([$hid]);foreach($q as $r)fputcsv($out,[$r['id'],$r['blood_group'],$r['units_needed'],$r['required_donors'],$r['urgency'],$r['district'],$r['status'],$r['created_at'],$r['expires_at']]);audit('hospital_csv_export','hospital',$hid,['type'=>'requests']);}fclose($out);exit;
